        frame.insertAdjacentHTML('beforeend', '<iframe src="'+src+'" title="Shrestha — video" allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture" allowfullscreen loading="lazy"></iframe>');
